with ins as (insert into public.artist_discography (artist_slug,artist_id,title,release_type,release_date,year,label,source_url) select x.s,a.id,x.ti,x.ty,x.d::date,x.y,x.l,x.u from json_to_recordset('[{"s":"su-real","ti":"SHAVA","ty":"single","y":2026,"d":"2026-05-05","l":null,"u":"https://realsureal.bandcamp.com/album/shava"},{"s":"su-real","ti":"PANJABI PARTY POPPERS 3","ty":"ep","y":2026,"d":"2026-10-07","l":null,"u":"https://realsureal.bandcamp.com/album/panjabi-party-poppers-3"}]'::json) as x(s text,ti text,ty text,y int,d text,l text,u text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_discography d where d.artist_slug=x.s and lower(d.title)=lower(x.ti)) on conflict do nothing returning 1) select count(*) from ins;